mapper.select:
SELECT
    *
FROM
    vm_ar_cruise_plan
WHERE
    delete_flag = '0'
AND tenant_id = #{param.tenantId}
AND industry_code = #{param.industryCode}
AND ar_view_id = #{param.arViewId}
AND channel_code = #{param.channelCode}
AND cruise_plan_name LIKE CONCAT('%',#{param.cruisePlanName},'%')
AND execution_status = #{param.executionStatus}
AND create_time BETWEEN CONCAT(#{param.queryTime}, ' 00:00:00') AND CONCAT(#{param.queryTime}, ' 23:59:59')
ORDER BY
    create_time DESC
